if (!defined('ABSPATH')) { exit; }

function ecoworld_crear_tabla() {
    global $wpdb;
    $tabla = $wpdb->prefix . 'ecoworld_certificados';
    $charset = $wpdb->get_charset_collate();
    require_once ABSPATH . 'wp-admin/includes/upgrade.php';
    dbDelta("CREATE TABLE $tabla (
        id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
        nombre varchar(150) NOT NULL,
        apellido varchar(150) NOT NULL,
        nacimiento date DEFAULT NULL,
        email varchar(254) NOT NULL DEFAULT '',
        email_estado varchar(30) NOT NULL DEFAULT 'not_sent',
        email_fecha datetime DEFAULT NULL,
        curso varchar(255) NOT NULL,
        horas smallint(5) unsigned DEFAULT NULL,
        tipo varchar(20) NOT NULL,
        fecha_emision date NOT NULL,
        codigo varchar(64) NOT NULL,
        estado varchar(20) NOT NULL DEFAULT 'vigente',
        PRIMARY KEY  (id),
        UNIQUE KEY codigo (codigo)
    ) $charset;");
    if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($tabla))) === $tabla) {
        update_option('ecoworld_certificados_schema', '1.2');
    }
}
register_activation_hook(__FILE__, 'ecoworld_crear_tabla');
add_action('admin_init', function () {
    if (current_user_can('manage_options') && get_option('ecoworld_certificados_schema') !== '1.2') {
        ecoworld_crear_tabla();
    }
});
function ecoworld_cursos() {
    return array(
        'Ultrasound Physics and Instrumentation with Point-of-Care Ultrasound (POCUS) Applications',
        'Abdominal and Small Parts Ultrasonography with Point-of-Care Ultrasound (POCUS) Applications',
        'Vascular Ultrasonography and Doppler Hemodynamics with Point-of-Care Ultrasound (POCUS) Applications',
        'Breast Ultrasonography with Point-of-Care Ultrasound (POCUS) Applications',
