        'Advanced Diploma in Emergency Medical Imaging with a Focus on Point-of-Care Ultrasound (POCUS)',
    );
}
function ecoworld_texto($datos, $campo) {
    return isset($datos[$campo]) && is_string($datos[$campo]) ? sanitize_text_field(wp_unslash($datos[$campo])) : '';
}
function ecoworld_fecha_valida($valor) {
    if (!preg_match('/^[1-9][0-9]{3}-[0-9]{2}-[0-9]{2}$/D', $valor)) { return false; }
    list($y, $m, $d) = array_map('intval', explode('-', $valor));
    return checkdate($m, $d, $y);
}
function ecoworld_largo($texto) {
    return function_exists('mb_strlen') ? mb_strlen($texto, 'UTF-8') : preg_match_all('/./us', $texto);
}
function ecoworld_url($codigo = '') {
    return add_query_arg('eco_verify', $codigo, home_url('/'));
}
function ecoworld_buscar($codigo) {
    global $wpdb;
    if (!preg_match('/^ECO-[A-F0-9]{32}$/D', $codigo)) { return null; }
    $tabla = $wpdb->prefix . 'ecoworld_certificados';
    // Birth dates are deliberately excluded from all certificate views.
    return $wpdb->get_row($wpdb->prepare("SELECT id,nombre,apellido,curso,horas,tipo,fecha_emision,codigo,estado FROM $tabla WHERE codigo = %s", $codigo));
}
