add_action('admin_post_ecoworld_guardar_certificado', 'ecoworld_guardar_certificado');
function ecoworld_guardar_certificado() {
    if (!current_user_can('manage_options')) { wp_die('Access denied.', '', array('response'=>403)); }
    if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') { wp_die('Invalid request.'); }
    check_admin_referer('ecoworld_emitir', 'ecoworld_nonce');
    $nombre = ecoworld_texto($_POST, 'eco_nombre'); $apellido = ecoworld_texto($_POST, 'eco_apellido');
    $curso = ecoworld_texto($_POST, 'eco_curso'); $tipo = ecoworld_texto($_POST, 'eco_tipo');
    $horas = filter_var(ecoworld_texto($_POST, 'eco_horas'), FILTER_VALIDATE_INT, array('options'=>array('min_range'=>1,'max_range'=>999)));
    $email = sanitize_email(ecoworld_texto($_POST, 'eco_email'));
    if (!is_email($email) || strlen($email) > 254) { wp_die('Enter a valid student email.'); }
    $fecha = ecoworld_texto($_POST, 'eco_fecha'); $nacimiento = ecoworld_texto($_POST, 'eco_nacimiento');
    if ($nombre === '' || $apellido === '' || !in_array($curso, ecoworld_cursos(), true) || ecoworld_largo($nombre)>150 || ecoworld_largo($apellido)>150 || $horas === false || !in_array($tipo, array('curso','evaluacion'), true)) { wp_die('Check the student name, course, course hours and certificate type.'); }
    if (!ecoworld_fecha_valida($fecha) || $fecha > current_time('Y-m-d') || ($nacimiento !== '' && (!ecoworld_fecha_valida($nacimiento) || $nacimiento > $fecha || $nacimiento > current_time('Y-m-d')))) { wp_die('Check the dates.'); }
    global $wpdb; $tabla = $wpdb->prefix . 'ecoworld_certificados';
    $codigo = 'ECO-' . strtoupper(str_replace('-', '', wp_generate_uuid4()));
    $ok = $wpdb->insert($tabla, array('nombre'=>$nombre,'apellido'=>$apellido,'email'=>$email,'nacimiento'=>$nacimiento === '' ? null : $nacimiento,'curso'=>$curso,'horas'=>$horas,'tipo'=>$tipo,'fecha_emision'=>$fecha,'codigo'=>$codigo,'estado'=>'vigente'), array('%s','%s','%s','%s','%s','%d','%s','%s','%s','%s'));
    if ($ok === false) { wp_die('The certificate could not be saved. Issuance has not been confirmed.'); }
    $id = (int) $wpdb->insert_id;
    $mail_status = ecoworld_enviar_pdf($id);
    wp_safe_redirect(add_query_arg(array('eco_guardado'=>$id, 'eco_mail'=>$mail_status), admin_url('admin.php?page=ecoworld-certificados'))); exit;
}
add_action('admin_post_ecoworld_estado', function () {
    if (!current_user_can('manage_options')) { wp_die('Access denied.', '', array('response'=>403)); }
    if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') { wp_die('Invalid request.'); }
    $id = absint(ecoworld_texto($_POST, 'id')); check_admin_referer('ecoworld_estado_' . $id);
    $estado = ecoworld_texto($_POST, 'estado');
    if (!$id || !in_array($estado, array('vigente','revocado'), true)) { wp_die('Invalid request.'); }
    global $wpdb;
    if ($wpdb->update($wpdb->prefix . 'ecoworld_certificados', array('estado'=>$estado), array('id'=>$id), array('%s'), array('%d')) === false) { wp_die('Status could not be updated.'); }
    wp_safe_redirect(admin_url('admin.php?page=ecoworld-certificados')); exit;
});
