// Small, self-contained PDF renderer. Fonts use Windows-1252 for Latin names.
function ecoworld_pdf_encode($text) {
    $text = preg_replace('/\s+/u', ' ', trim($text));
    if (function_exists('iconv')) {
        $encoded = @iconv('UTF-8', 'Windows-1252//TRANSLIT//IGNORE', $text);
        if ($encoded !== false) { return $encoded; }
    }
    $text = remove_accents($text);
    return preg_replace('/[^\x20-\x7e]/', '', $text);
}
function ecoworld_pdf_escape($text) {
    return str_replace(array('\\', '(', ')', "\r", "\n"), array('\\\\', '\\(', '\\)', '', ' '), $text);
}
function ecoworld_pdf_width($text, $size, $bold = false) {
    $widths = ecoworld_pdf_widths(); $map = $widths[$bold ? 1 : 0]; $width = 0;
    for ($i=0; $i<strlen($text); $i++) { $width += $map[ord($text[$i])] ?? 600; }
    return $width * $size / 1000;
}
function ecoworld_pdf_bytes($r) {
    $stream = "0.025 0.12 0.28 RG 2 w 15 15 812 565 re S\n0.08 0.46 0.37 RG 0.7 w 23 23 796 549 re S\n";
    $stream .= "0.025 0.12 0.28 rg 15 490 m 15 580 l 235 580 l h f\n0.08 0.46 0.37 rg 15 478 m 15 490 l 235 580 l 260 580 l h f\n";
    $stream .= "0.025 0.12 0.28 rg 827 105 m 827 15 l 607 15 l h f\n0.08 0.46 0.37 rg 827 117 m 827 105 l 607 15 l 582 15 l h f\n";
    $center = function ($text, $y, $size, $bold = false, $color = '0.025 0.12 0.28') use (&$stream) {
        $encoded = ecoworld_pdf_encode($text); $w = ecoworld_pdf_width($encoded,$size,$bold);
        $x = (842 - $w) / 2;
        $stream .= sprintf("%s rg BT /%s %.2F Tf 1 0 0 1 %.2F %.2F Tm (%s) Tj ET\n", $color, $bold ? 'F2' : 'F1', $size, $x, $y, ecoworld_pdf_escape($encoded));
    };
    $fit = function($text,$y,$start,$minimum,$bold=false,$color='0.025 0.12 0.28') use ($center) {
        $size=$start; $encoded=ecoworld_pdf_encode($text);
        while ($size>$minimum && ecoworld_pdf_width($encoded,$size,$bold)>700) { $size-=0.5; }
        // Wrap even long, unbroken names using exact font metrics.
        $lines=array(''); $n=0;
        for ($i=0;$i<strlen($encoded);$i++) {
            if (ecoworld_pdf_width($lines[$n].$encoded[$i],$size,$bold)>700) { $lines[++$n]=''; }
            $lines[$n].=$encoded[$i];
        }
        if (count($lines)>3) { throw new RuntimeException('Certificate text is too long for the PDF layout.'); }
        foreach($lines as $line) {
            $unicode = function_exists('iconv') ? iconv('Windows-1252','UTF-8',$line) : $line;
            $center($unicode,$y,$size,$bold,$color); $y-=$size*1.2;
        }
    };
    $stream .= "q 100 0 0 100 295 453 cm /Im1 Do Q\nq 115 0 0 115 438 445 cm /Im2 Do Q\n";
    $center('CERTIFICATE',414,40,true);
    $center($r->tipo === 'evaluacion' ? 'OF ACHIEVEMENT' : 'OF COMPLETION',384,18,true,'0.08 0.46 0.37');
    $center('AWARDED TO',350,11,true);
    $fit($r->nombre.' '.$r->apellido,313,30,7,true);
    $stream .= "0.35 0.45 0.56 RG 0.6 w 100 263 m 742 263 l S\n";
    $center($r->tipo === 'evaluacion' ? 'For successfully passing the assessment for' : 'For successfully completing the course',239,13);
    $fit($r->curso,210,22,8,true,'0.08 0.46 0.37');
    if (!empty($r->horas)) { $center('Course Hours: '.(int) $r->horas.' hours',174,12); }
    $date=DateTime::createFromFormat('!Y-m-d',$r->fecha_emision);
    $center('Date of Issue: '.($date ? $date->format('F j, Y') : $r->fecha_emision),155,12);
    $stream .= "0.35 0.45 0.56 RG 0.5 w 100 119 m 355 119 l S 487 119 m 742 119 l S\n";
    $left=ecoworld_pdf_escape(ecoworld_pdf_encode('Dr. José David Carrillo Ojeda'));
    $stream .= "0.025 0.12 0.28 rg BT /F2 10 Tf 1 0 0 1 151 103 Tm (ACADEMIC DIRECTOR) Tj ET\nBT /F1 10 Tf 1 0 0 1 153 88 Tm ($left) Tj ET\nBT /F1 9 Tf 1 0 0 1 169 74 Tm (CEO - Ecoworld Class) Tj ET\n";
    $coordination_name=ecoworld_pdf_encode('Dra. Yareltsi Cristina Espinoza Salazar');
    $coordination_x=614-ecoworld_pdf_width($coordination_name,9)/2;
    $coordination_name=ecoworld_pdf_escape($coordination_name);
    $stream .= "BT /F2 10 Tf 1 0 0 1 540 103 Tm (GENERAL COORDINATION) Tj ET\nBT /F1 9 Tf 1 0 0 1 ".sprintf('%.2F',$coordination_x)." 88 Tm ($coordination_name) Tj ET\nBT /F1 9 Tf 1 0 0 1 577 74 Tm (Ecoworld Class) Tj ET\n";
    $center('Certificate ID: '.$r->codigo,54,9);
    $center('Verify online: '.ecoworld_url(),40,8);
    $center('Issued by Ecoworld Class. Does not confer ARDMS credentials or a professional license.',28,7);
    $images=ecoworld_pdf_images();
    $images[]=ecoworld_pdf_signature_image('https://ecoworldclass.com/wp-content/uploads/2026/10/Firma-manuscrita-sobre-fondo-blanco-1.png');
    $images[]=ecoworld_pdf_signature_image('https://ecoworldclass.com/wp-content/uploads/2026/10/Firma-manuscrita-sobre-fondo-blanco.png');
    foreach(array(2=>227.5,3=>614.5) as $image_index=>$center_x) {
        $image=$images[$image_index];
        $scale=min(165/$image[0],44/$image[1]);
        $width=$image[0]*$scale; $height=$image[1]*$scale;
        $x=$center_x-$width/2; $y=121+(44-$height)/2;
        $stream.=sprintf("q %.2F 0 0 %.2F %.2F %.2F cm /Im%d Do Q\n",$width,$height,$x,$y,$image_index+1);
    }
    $objects=array(
        '<< /Type /Catalog /Pages 2 0 R >>',
        '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
        '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> /XObject << /Im1 7 0 R /Im2 8 0 R /Im3 9 0 R /Im4 10 0 R >> >> /Contents 6 0 R /Annots [11 0 R] >>',
        ecoworld_pdf_font_object(0, 12),
        ecoworld_pdf_font_object(1, 14),
        '<< /Length '.strlen($stream).">>\nstream\n".$stream."endstream"
    );
    foreach($images as $img) { $data=base64_decode($img[2],true); if($data===false){throw new RuntimeException('Invalid logo.');} $objects[]='<< /Type /XObject /Subtype /Image /Width '.$img[0].' /Height '.$img[1].' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '.strlen($data).">>\nstream\n".$data."\nendstream"; }
    $uri=ecoworld_pdf_escape(ecoworld_url($r->codigo));
    $objects[]='<< /Type /Annot /Subtype /Link /Rect [100 35 742 64] /Border [0 0 0] /A << /S /URI /URI ('.$uri.') >> >>';
    foreach(ecoworld_pdf_fonts() as $i=>$font) {
        $data=base64_decode($font[0],true); $fileid=$i === 0 ? 13 : 15;
        $objects[]='<< /Type /FontDescriptor /FontName /'.$font[1].' /Flags 32 /FontBBox ['.implode(' ',$font[2]).'] /ItalicAngle 0 /Ascent '.$font[3].' /Descent '.$font[4].' /CapHeight 730 /StemV 80 /FontFile2 '.$fileid.' 0 R >>';
        $objects[]='<< /Length '.strlen($data).' /Length1 '.strlen($data).">>\nstream\n".$data."\nendstream";
    }
    $pdf="%PDF-1.4\n%\xe2\xe3\xcf\xd3\n"; $offsets=array(0);
    foreach($objects as $i=>$object){$offsets[]=strlen($pdf);$pdf.=($i+1)." 0 obj\n".$object."\nendobj\n";}
    $xref=strlen($pdf);$pdf.="xref\n0 ".(count($objects)+1)."\n0000000000 65535 f \n";
    foreach(array_slice($offsets,1) as $offset){$pdf.=sprintf("%010d 00000 n \n",$offset);}
    return $pdf.'trailer << /Size '.(count($objects)+1).' /Root 1 0 R >>'."\nstartxref\n".$xref."\n%%EOF\n";
}
function ecoworld_email_body($r) {
    $name=esc_html($r->nombre.' '.$r->apellido); $course=esc_html($r->curso);
    $achievement=$r->tipo === 'evaluacion' ? 'successfully passing the assessment for' : 'successfully completing';
    return '<html><body style="font-family:Arial,sans-serif;color:#10294c;line-height:1.7"><div style="max-width:650px;margin:auto;padding:30px;border-top:6px solid #147566">'
        .'<h1 style="color:#147566">Congratulations on your achievement!</h1><p>Dear '.$name.',</p>'
        .'<p>On behalf of Ecoworld Class, I am delighted to congratulate you on '.$achievement.' <strong>'.$course.'</strong>.</p>'
        .'<p>Your dedication, commitment to learning, and effort deserve recognition. It is a privilege to be part of your educational journey, and I encourage you to continue developing your knowledge and skills with confidence and purpose.</p>'
        .'<p>Please find your certificate attached as a PDF. Keep it as a record of this achievement. You can also view and verify it online using the link below.</p>'
        .'<p><a href="'.esc_url(ecoworld_url($r->codigo)).'" style="background:#0b315e;color:#fff;padding:12px 20px;text-decoration:none">View and Verify Your Certificate</a></p>'
        .'<p><strong>Certificate ID:</strong> '.esc_html($r->codigo).'</p>'
        .'<p>Thank you for choosing Ecoworld Class. We look forward to seeing you continue to grow and reach new goals.</p>'
        .'<p>With warm congratulations,</p><p><strong>Dr. José David Carrillo Ojeda</strong><br>Physician<br>Founder &amp; CEO | Academic Director<br><strong>Ecoworld Class</strong><br><a href="https://ecoworldclass.com">ecoworldclass.com</a></p>'
        .'<p style="font-size:11px;color:#657080">This certificate is issued by Ecoworld Class and does not confer POCUS orARDMS credentials or a professional license.</p></div></body></html>';
}
function ecoworld_enviar_pdf($id) {
    global $wpdb; $tabla=$wpdb->prefix.'ecoworld_certificados';
    $r=$wpdb->get_row($wpdb->prepare("SELECT * FROM $tabla WHERE id = %d",$id));
    if(!$r || $r->estado!=='vigente' || !is_email($r->email)){return 'mail_error';}
    // Keep private attachments in a random system temporary directory, never in public uploads.
    $status='pdf_error'; $directory=''; $file='';
    try {
        $pdf=ecoworld_pdf_bytes($r);
        $directory=rtrim(sys_get_temp_dir(),'/\\').'/ecoworld-'.str_replace('-','',wp_generate_uuid4());
        if(!is_writable(sys_get_temp_dir()) || !mkdir($directory,0700)){throw new RuntimeException('Cannot create temporary directory.');}
        $file=$directory.'/'.$r->codigo.'.pdf';
        if(file_put_contents($file,$pdf)!==strlen($pdf)){throw new RuntimeException('Cannot write PDF.');}
        @chmod($file,0600);
        $status='mail_error';
        $sent=wp_mail($r->email,'Congratulations! Your Ecoworld Class Certificate',ecoworld_email_body($r),array('Content-Type: text/html; charset=UTF-8'),array($file));
        if($sent){$status='accepted';}
    } catch(Throwable $e) {
        // Do not expose student data or transport errors on public pages.
    } finally {
        if($file && is_file($file)){unlink($file);} if($directory && is_dir($directory)){rmdir($directory);}
    }
    $wpdb->update($tabla,array('email_estado'=>$status,'email_fecha'=>current_time('mysql')),array('id'=>$id),array('%s','%s'),array('%d'));
    return $status;
}
add_action('admin_post_ecoworld_reenviar',function(){
    if(!current_user_can('manage_options')){wp_die('Access denied.','',array('response'=>403));}
    if(($_SERVER['REQUEST_METHOD'] ?? '')!=='POST'){wp_die('Invalid request.');}
    $id=absint(ecoworld_texto($_POST,'id')); check_admin_referer('ecoworld_reenviar_'.$id);
    $email=sanitize_email(ecoworld_texto($_POST,'eco_email'));
    if(!$id || !is_email($email) || strlen($email)>254){wp_die('Enter a valid student email.');}
    global $wpdb; $tabla=$wpdb->prefix.'ecoworld_certificados';
    $r=$wpdb->get_row($wpdb->prepare("SELECT id,estado FROM $tabla WHERE id = %d",$id));
    if(!$r || $r->estado!=='vigente'){wp_die('Only valid certificates can be sent.');}
    if($wpdb->update($tabla,array('email'=>$email),array('id'=>$id),array('%s'),array('%d'))===false){wp_die('Email could not be updated.');}
    $status=ecoworld_enviar_pdf($id);
    wp_safe_redirect(add_query_arg('eco_mail',$status,admin_url('admin.php?page=ecoworld-certificados')));exit;
});

