function ecoworld_pdf_signature_image($url) {
    $cache_key='ecoworld_pdf_signature_'.md5($url);
    $cached=get_transient($cache_key);
    if(is_array($cached) && isset($cached[0],$cached[1],$cached[2])) { return $cached; }
    $response=wp_safe_remote_get($url,array('timeout'=>12,'redirection'=>3,'limit_response_size'=>2097152));
    if(is_wp_error($response) || wp_remote_retrieve_response_code($response)!==200) { throw new RuntimeException('Could not download certificate signature.'); }
    $body=wp_remote_retrieve_body($response);
    $temporary=wp_tempnam($url);
    if(!$temporary || file_put_contents($temporary,$body)!==strlen($body)) { if($temporary){@unlink($temporary);} throw new RuntimeException('Could not save certificate signature.'); }
    $jpeg=$temporary.'.jpg';
    try {
        $editor=wp_get_image_editor($temporary);
        if(is_wp_error($editor)) { throw new RuntimeException('Could not process certificate signature.'); }
        $editor->resize(800,300,false);
        $saved=$editor->save($jpeg,'image/jpeg');
        if(is_wp_error($saved)) { throw new RuntimeException('Could not convert certificate signature.'); }
        $dimensions=@getimagesize($jpeg); $data=@file_get_contents($jpeg);
        if(!$dimensions || $dimensions['mime']!=='image/jpeg' || $data===false) { throw new RuntimeException('Invalid certificate signature image.'); }
        $image=array((int)$dimensions[0],(int)$dimensions[1],base64_encode($data));
        set_transient($cache_key,$image,DAY_IN_SECONDS);
        return $image;
    } finally {
        @unlink($temporary); @unlink($jpeg);
    }
}

