function ecoworld_pdf_fonts() { return array(array("", "DejaVuSans", array(-411, -261, 1287, 946), 928, -236), array("", "DejaVuSans-Bold", array(-435, -236, 1417, 931), 928, -236)); }
function ecoworld_pdf_font_object($i,$descriptor) {
    $fonts=ecoworld_pdf_fonts();$widths=ecoworld_pdf_widths();
    return '<< /Type /Font /Subtype /TrueType /BaseFont /'.$fonts[$i][1].' /FirstChar 32 /LastChar 255 /Widths ['.implode(' ',array_slice($widths[$i],32)).'] /Encoding /WinAnsiEncoding /FontDescriptor '.$descriptor.' 0 R >>';
}
